using Shouldly;

namespace Dracocephalum.Spice.Translation.Tests;

public class ToolkitHeaderTests
{
    private const string Unit =
        """
        // <auto-generated>
        // Translated from FORTRAN 77 by Fortrania: VADD, from vadd.f.
        // A change made here is lost when the source is translated again.
        // </auto-generated>

        namespace Example;
        """;

    [Fact]
    public void AddTo_WhenTheFileIsAProgramUnit_ShouldNameItInsideTheGeneratedBlock()
    {
        // Act
        var text = ToolkitHeader.AddTo(Unit.ReplaceLineEndings("\n"));

        // Assert
        text.ShouldBe(
            """
            // <auto-generated>
            // Translated from FORTRAN 77 by Fortrania: VADD, from vadd.f.
            // A change made here is lost when the source is translated again.
            // Machine translation of VADD, from vadd.f, of NASA's SPICE Toolkit N0067.
            // It is not a product of NASA, of Caltech/JPL or of NAIF, the Navigation and
            // Ancillary Information Facility that maintains the toolkit, and NAIF does
            // not support it. The toolkit's rules apply to it, and not the licence of
            // the repository it is kept in; see LICENSE.md beside the project.
            // </auto-generated>

            namespace Example;
            """.ReplaceLineEndings("\n"));
    }

    [Fact]
    public void AddTo_WhenTheFileWasChangedAfterTranslation_ShouldSaySo()
    {
        // Act
        var text = ToolkitHeader.AddTo(Unit.ReplaceLineEndings("\n"), "it reports the platform it runs on.");

        // Assert
        text.ShouldContain("// the repository it is kept in; see LICENSE.md beside the project.\n// Changed after translation by Dracocephalum.Spice.Translation: it reports the platform it runs on.\n// </auto-generated>\n");
    }

    [Fact]
    public void AddTo_WhenTheFileIsNoProgramUnit_ShouldSayItIsPartOfTheTranslation()
    {
        // Arrange
        const string Class = "// <auto-generated>\n// Written by Fortrania with the code it translated from FORTRAN 77.\n// </auto-generated>\n";

        // Act
        var text = ToolkitHeader.AddTo(Class);

        // Assert
        text.ShouldContain("// Machine translation of part of NASA's SPICE Toolkit N0067.\n");
    }

    [Fact]
    public void AddTo_WhenTheHeaderIsThereAlready_ShouldChangeNothing()
    {
        // Arrange
        var once = ToolkitHeader.AddTo(Unit.ReplaceLineEndings("\n"));

        // Act
        var twice = ToolkitHeader.AddTo(once, "it reports the platform it runs on.");

        // Assert
        twice.ShouldBe(once);
    }

    [Fact]
    public void AddTo_WhenTheFileHasNoGeneratedBlock_ShouldRefuse()
    {
        // Act & Assert
        Should.Throw<RewriteException>(() => ToolkitHeader.AddTo("namespace Example;\n"));
    }
}
